```json
{
  "id": "onebit-dither-sphere",
  "name": "Bayer Corner Falloff",
  "idea": "A soft light falloff in the top right corner resolved only by an ordered 8 by 8 Bayer dither on a pixel-exact grid, its threshold breathing and drifting slowly, while a thin inverted selection band now and then slides in from the right edge, holds, and retracts.",
  "use": [
    "hero",
    "empty-state",
    "loading",
    "paywall-plan"
  ],
  "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float b2(vec2 a){a=floor(a);return fract(a.x*0.5+a.y*a.y*0.75);}
float b4(vec2 a){return b2(0.5*a)*0.25+b2(a);}
float b8(vec2 a){return b4(0.5*a)*0.25+b2(a);}
void main(){
float s=max(2.0,floor(u_resolution.y/300.0));
vec2 q=floor(gl_FragCoord.xy/s);
vec2 p=(q*s+0.5*s-0.5*u_resolution)/u_resolution.y;
float ar=u_resolution.x/u_resolution.y;
float t=u_time;
vec2 c=vec2(0.5*ar-0.04+0.05*sin(t*0.31),0.52+0.03*cos(t*0.23));
float rad=mix(0.62,1.0,clamp(ar-0.4,0.0,1.0))+0.08*sin(t*0.52);
float d=length((p-c)*vec2(1.0,1.15));
float f=pow(max(1.0-d/rad,0.0),1.7);
f*=1.0+0.14*sin(dot(p,vec2(2.6,1.9))*3.0-t*0.7);
float th=b8(q);
float on=step(th+0.02,f*0.94);
float ph=t/14.0;
float k=fract(ph);
float w=smoothstep(0.08,0.2,k)*(1.0-smoothstep(0.55,0.67,k));
float row=mod(floor(ph),3.0);
float by=0.36-row*0.11;
float wmax=0.3*ar+0.12;
float xr=0.5*ar-0.03;
float band=step(abs(p.y-by),0.026)*step(xr-w*wmax,p.x)*step(p.x,xr)*step(0.01,w);
vec2 g=mod(q,8.0);
float dots=step(g.x,0.5)*step(g.y,0.5)*(1.0-smoothstep(0.0,0.3,f));
vec3 ink=mix(u_c3,u_c1,smoothstep(0.55,0.9,f));
vec3 col=u_c0+u_c3*dots*0.12;
col=mix(col,ink,on);
vec3 sel=mix(u_c2*0.92+u_c0*0.08,u_c0,on);
col=mix(col,sel,band);
gl_FragColor=vec4(col,1.0);
}",
  "colors": [
    "#000000",
    "#ffffff",
    "#ffffff",
    "#aaaaaa"
  ],
  "reduced": {
    "kind": "fade",
    "at": 5,
    "ms": 400,
    "note": "A still dithered glow in the top right corner with one inverted selection band across it, the rest of the frame flat."
  },
  "cardIds": [
    "1-bit-gui-1984"
  ],
  "lensIds": [],
  "styles": [
    "retro-pixel-halftone"
  ]
}
```

```json
{
  "id": "blueprint-circle-draft",
  "name": "Hairline Draft Rest",
  "idea": "On a deep navy sheet with a barely visible hairline grid, three thin lines slowly extend along the grid near the top and right edges, gain small dimension ticks at their ends, and one yellow point settles where the first line stops, then the work quietly fades and is drafted again.",
  "use": [
    "hero",
    "empty-state",
    "loading",
    "onboarding-slide"
  ],
  "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float ln(float d){return 1.0-smoothstep(0.35,1.85,d);}
float sn(float v){return floor(v/24.0+0.5)*24.0;}
float sg(vec2 q,float y,float a,float b,float pr){
float e=mix(a,b,pr);
float w=18.0*(1.0-pr)+0.5;
return ln(abs(q.y-y))*step(a,q.x)*(1.0-smoothstep(e-w,e+0.5,q.x))*step(0.001,pr);
}
float mk(vec2 d){
float tk=ln(abs(d.x-d.y)*0.7071)*step(length(d),6.0);
float ex=ln(abs(d.x))*step(abs(d.y),10.0);
return max(tk,ex*0.7);
}
void main(){
vec2 R=u_resolution;
vec2 f=gl_FragCoord.xy;
vec2 p=(f-0.5*R)/R.y;
float t=u_time;
float ph=fract(t/18.0);
float vis=smoothstep(0.0,0.03,ph)*(1.0-smoothstep(0.88,0.99,ph));
vec3 col=u_c0;
vec2 v=p*vec2(0.5,0.7);
col*=1.0-0.25*dot(v,v);
col=mix(col,u_c3,0.06*smoothstep(1.2,0.0,length(p-vec2(-0.5*R.x/R.y,0.45))));
vec2 g=abs(fract(f/24.0+0.5)-0.5)*24.0;
vec2 G=abs(fract(f/120.0+0.5)-0.5)*120.0;
float gr=0.06*ln(min(g.x,g.y))+0.08*ln(min(G.x,G.y));
col=mix(col,u_c3,gr*1.5);
float x0=sn(R.x*0.08);
float x1=sn(R.x*0.58);
float x2=sn(R.x*0.34);
float y1=sn(R.y*0.86);
float y2=y1-48.0;
float xv=sn(R.x*0.92);
float yv0=sn(R.y*0.22);
float yv1=sn(R.y*0.62);
float p1=smoothstep(0.04,0.30,ph);
float p2=smoothstep(0.14,0.36,ph);
float p3=smoothstep(0.30,0.58,ph);
float L=sg(f,y1,x0,x1,p1)+0.7*sg(f,y2,x0,x2,p2)+0.8*sg(vec2(-f.y,f.x),xv,-yv1,-yv0,p3);
float mt=0.6*ln(G.x)*step(abs(f.y-y1),3.5)*step(x0+1.0,f.x)*step(f.x,mix(x0,x1,p1)-6.0);
float m=mk(f-vec2(x0,y1))*step(0.001,p1)+mk(f-vec2(x1,y1))*smoothstep(0.9,1.0,p1);
m+=0.7*(mk(f-vec2(x0,y2))*step(0.001,p2)+mk(f-vec2(x2,y2))*smoothstep(0.9,1.0,p2));
m+=0.8*(mk((f-vec2(xv,yv1)).yx)*step(0.001,p3)+mk((f-vec2(xv,yv0)).yx)*smoothstep(0.9,1.0,p3));
col=mix(col,u_c1,clamp(L+m+mt,0.0,1.0)*0.42*vis);
float ad=length(f-vec2(x1,y1));
float ap=smoothstep(0.30,0.40,ph)*vis;
float br=0.85+0.15*sin(t*6.2832/7.0);
float dt=1.0-smoothstep(2.5,4.0,ad);
float gl=exp(-ad*ad/900.0)*0.18*br;
